DO $roles$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'anon') THEN CREATE ROLE anon NOLOGIN; END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'authenticated') THEN CREATE ROLE authenticated NOLOGIN; END IF;
END;
$roles$;

CREATE TABLE public.web_orders (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  client_reference text NOT NULL UNIQUE,
  payment_method text NOT NULL,
  customer_cedula text NOT NULL,
  status text NOT NULL DEFAULT 'pending'
);

-- Legacy fixture intentionally predates the trigger and contains whitespace.
INSERT INTO public.web_orders(client_reference, payment_method, customer_cedula)
VALUES ('LEGACY-COD-REF', 'Contra entrega', '   ');

-- Synthetic stand-in for the existing insert-only idempotent COD core: existing
-- references return before INSERT; new references reach the table trigger.
CREATE FUNCTION public.fixture_cod_submit(p_reference text, p_cedula text)
RETURNS jsonb
LANGUAGE plpgsql
AS $function$
DECLARE
  v_order public.web_orders%ROWTYPE;
BEGIN
  SELECT * INTO v_order
  FROM public.web_orders
  WHERE client_reference = p_reference AND payment_method = 'Contra entrega';
  IF FOUND THEN
    IF coalesce(v_order.customer_cedula, '') <> coalesce(p_cedula, '') THEN
      RETURN jsonb_build_object('success', false, 'duplicate', true, 'message', 'legacy_mismatch');
    END IF;
    RETURN jsonb_build_object('success', true, 'duplicate', true, 'order_id', v_order.id);
  END IF;
  INSERT INTO public.web_orders(client_reference, payment_method, customer_cedula)
  VALUES (p_reference, 'Contra entrega', coalesce(p_cedula, ''))
  RETURNING * INTO v_order;
  RETURN jsonb_build_object('success', true, 'duplicate', false, 'order_id', v_order.id);
END;
$function$;
